INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q1 Item 1 (TPS 2017): Com base nas ideias expressas no texto I, julgue (C ou E) os itens a seguir. | Embora seja um objeto importante nos dois romances mencionados — O Mulato e Memórias Póstumas de Brás Cubas —, o “sinete” (R.82) mostra-se fundamental no romance de Aluísio Azevedo, de feição naturalista.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q1 Item 2 (TPS 2017): Com base nas ideias expressas no texto I, julgue (C ou E) os itens a seguir. | Segundo a autora do texto, o elemento de escândalo social intrínseco à temática de Memórias Póstumas de Brás Cubas não foi compreendido pelo meio intelectual, nem pelo público, no momento da publicação do romance na Revista Brasileira, em 1880, tampouco em seu lançamento em formato de livro, em 1881.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q1 Item 3 (TPS 2017): Com base nas ideias expressas no texto I, julgue (C ou E) os itens a seguir. | A autora argumenta, no texto, que o romance de Machado de Assis é representante de uma tendência analítica em literatura, ao passo que O Mulato demonstra tendência descritiva, tendo alcançado, na época de sua publicação, maior popularidade que Memórias Póstumas de Brás Cubas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q1 Item 4 (TPS 2017): Com base nas ideias expressas no texto I, julgue (C ou E) os itens a seguir. | É possível concluir do texto que, tal como aconteceu em 1822 no plano político, a “independência literária” (R.41) de 1881 caracterizou-se como um movimento de “liberdade de concepção e expressão” (R. 44 e 45), uma vez que tanto O Mulato quanto Memórias Póstumas de Brás Cubas expressaram o afastamento de seus autores da submissão intelectual a escritores estrangeiros, como Zola e Eça de Queirós. CESPE | CEBRASPE – IRBr – Aplicação: 2017', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q2 Item 1 (TPS 2017): Com relação a aspectos gramaticais do texto I, julgue (C ou E) os itens que se seguem. 1 Sem prejuízo das informações originais do texto e de sua correção gramatical, o trecho “Abandonando os episódios sentimentais (...) larga e profundamente humano” (R. 71 a 76) poderia ser reescrito da seguinte forma: Ao abandonar os episódios sentimentais que até esse momento se tenha privilegiado e ao instalar-se no íntimo de suas criaturas, descobriu, Machado de Assis, seres em que reações tipicamente brasi | Dei em passear de bonde, saltando de um para outro, aventurando-me por travessas afastadas, para buscar o veículo em outros bairros. Da Tijuca ia ao Andaraí e daí à Vila Isabel;', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q2 Item 2 (TPS 2017): Com relação a aspectos gramaticais do texto I, julgue (C ou E) os itens que se seguem. 1 Sem prejuízo das informações originais do texto e de sua correção gramatical, o trecho “Abandonando os episódios sentimentais (...) larga e profundamente humano” (R. 71 a 76) poderia ser reescrito da seguinte forma: Ao abandonar os episódios sentimentais que até esse momento se tenha privilegiado e ao instalar-se no íntimo de suas criaturas, descobriu, Machado de Assis, seres em que reações tipicamente brasi | e assim, passando de um bairro para outro, procurando travessas despovoadas e sem calçamento, conheci a cidade — tal qual os bondes a fizeram alternativamente povoada 7 e despovoada, com grandes hiatos entre ruas de população condensada e toda ela, agitada, dividida, convulsionada pelas colinas e contrafortes da montanha em cujas vertentes 10 crescera. Jantava, uns dias; em outros, almoçava unicamente; e houve muitos que nem uma coisa ou outra fiz. (...) Abelardo Leiva, ', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q3 Item 1 (TPS 2017): Com relação às ideias desenvolvidas no texto II, julgue (C ou E) os itens subsequentes. | No texto, o narrador emprega a expressão “grandes hiatos”(R.7) para se referir a locais despovoados da cidade, que ele ia conhecendo de bonde.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q3 Item 2 (TPS 2017): Com relação às ideias desenvolvidas no texto II, julgue (C ou E) os itens subsequentes. | O narrador supõe existir um “verdadeiro Leiva” (R.64), que se vislumbra na “poesia palaciana e de modista” (R.59) deste personagem, e imagina que, caso passasse a viver em condições econômicas mais favoráveis, Leiva se revelaria descrente dos ideais revolucionários e atraído pelo conforto material.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q3 Item 3 (TPS 2017): Com relação às ideias desenvolvidas no texto II, julgue (C ou E) os itens subsequentes. | O narrador discorda da opinião geral dos amigos de Leiva, que o julgam “perfeitamente hipócrita” (R.60), e considera que tal julgamento advém do meio pobre e humilde que Leiva frequenta.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q3 Item 4 (TPS 2017): Com relação às ideias desenvolvidas no texto II, julgue (C ou E) os itens subsequentes. | Nos trechos “Eu gostava de notar a adoração pela violência que as suas almas pacíficas tinham” (R. 34 e 35) e “Era um grupo de protestantes, detestando a política” (R. 48 e 49), o narrador alude a uma ambivalência no comportamento de Leiva e de seus amigos. CESPE | CEBRASPE – IRBr – Aplicação: 2017', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q4 Item 1 (TPS 2017): Considerando as relações semântico-sintáticas estabelecidas no texto II, julgue (C ou E) os itens a seguir. 1 No período “Creio que lhes não faltava inteligência, sinceridade também; o que não encontravam era uma soma de necessidades a que viessem responder e sobre as quais apoiassem as suas furiosas declamações” (R. 38 a 41), as negações enfatizam a sequência de características depreciativas atribuídas ao grupo de Leiva, para o que contribui o emprego do adjetivo “furiosas” e do modo subjuntivo | Escrita em prosa e verso, a Carta Marítima é formalmente um poema sui generis, que supera as divisões convencionais do discurso. Quanto à mensagem, tem elementos', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q4 Item 2 (TPS 2017): Considerando as relações semântico-sintáticas estabelecidas no texto II, julgue (C ou E) os itens a seguir. 1 No período “Creio que lhes não faltava inteligência, sinceridade também; o que não encontravam era uma soma de necessidades a que viessem responder e sobre as quais apoiassem as suas furiosas declamações” (R. 38 a 41), as negações enfatizam a sequência de características depreciativas atribuídas ao grupo de Leiva, para o que contribui o emprego do adjetivo “furiosas” e do modo subjuntivo | de uma alegre sátira ideologicamente avançada para o acanhado meio português do tempo, na qual Sousa Caldas censura os privilégios e a vida materializada, presa a uma 7 educação artificial e obsoleta, sugerindo a regeneração da sociedade por meio de uma transformação como a que lhe parecia estar em curso na França revolucionária. 10 No plano cultural, satiriza a tirania da herança greco-latina e aspira a algo diferente, que não formula, sendo porém significativo que enqu', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q5 Item 1 (TPS 2017): Julgue (C ou E) os itens seguintes, relacionados às ideias desenvolvidas no texto III. | Antonio Candido afirma que Sousa Caldas, em Carta Marítima, escreveu um poema satírico que mostrava avanços em relação ao seu tempo, até mesmo pelo fato de o poeta fazer referência laudatória a um escritor como Miguel de Cervantes.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q5 Item 2 (TPS 2017): Julgue (C ou E) os itens seguintes, relacionados às ideias desenvolvidas no texto III. | De acordo com Antonio Candido, os autores românticos, entre eles Gonçalves de Magalhães, não fizeram referência à Carta Marítima, apesar de Sousa Caldas ser um poeta conhecido naquele momento e de o poema conter aspectos modernizadores buscados pela poesia romântica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q5 Item 3 (TPS 2017): Julgue (C ou E) os itens seguintes, relacionados às ideias desenvolvidas no texto III. | Segundo o texto, Sousa Caldas, em Carta Marítima, repudiou os temas religiosos e preferiu salientar os mitos da Antiguidade clássica que permitissem fazer uma sátira surpreendente no meio social do seu tempo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q5 Item 4 (TPS 2017): Julgue (C ou E) os itens seguintes, relacionados às ideias desenvolvidas no texto III. | Conclui-se do texto que Sousa Caldas, ao escrever a Carta Marítima, prenunciou o Romantismo brasileiro, tendo criticado a “exaustão literária” (R. 37 e 38) da poesia de Gonçalves de Magalhães, que, no ano anterior, havia publicado um volume pífio intitulado Poesias. CESPE | CEBRASPE – IRBr – Aplicação: 2017', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q6 Item 1 (TPS 2017): Com relação a aspectos gramaticais do texto III, julgue (C ou E) os próximos itens. | A substituição do vocábulo “encharcado” (R.37) por repleto preservaria o estilo original do período, embora acarretasse prejuízo ao teor metafórico da construção.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q6 Item 2 (TPS 2017): Com relação a aspectos gramaticais do texto III, julgue (C ou E) os próximos itens. | A substituição da conjunção “embora” (R.29) pela conjunção conquanto prejudicaria o sentido original do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q6 Item 3 (TPS 2017): Com relação a aspectos gramaticais do texto III, julgue (C ou E) os próximos itens. | A substituição da oração relativa “que não formula” (R.11) por embora não a formule manteria o sentido original do texto e sua correção gramatical, desde que fossem mantidas as vírgulas que isolam referida oração.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q6 Item 4 (TPS 2017): Com relação a aspectos gramaticais do texto III, julgue (C ou E) os próximos itens. | Dados os sentidos do texto, é correto afirmar que os sujeitos elípticos das formas verbais “privilegia” (R.14) e “reforça” (R.16) têm referentes distintos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q7 Item 1 (TPS 2017): Com relação a aspectos linguísticos e textuais do texto III, julgue (C ou E) os seguintes itens. 1 Com o emprego de construções como “Vistas as coisas de hoje” (R.43) e “Difícil imaginar os motivos” (R.48) e da forma verbal “pensamos” (R.49), o autor confere um tom impessoal ao texto. 2 Os adjetivos “pífio” (R.36) e “encharcado” (R.37) e a expressão “exaustão literária” (R. 37 e 38) são empregados, no texto, em sentido conotativo. 3 Sem prejuízo das informações originais do texto e de sua correç | A classe dedicada ao comércio, marcada pela compra e venda de mercadorias ou na colocação de dinheiro, não representava, no Império, o padrão social dominante.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q7 Item 2 (TPS 2017): Com relação a aspectos linguísticos e textuais do texto III, julgue (C ou E) os seguintes itens. 1 Com o emprego de construções como “Vistas as coisas de hoje” (R.43) e “Difícil imaginar os motivos” (R.48) e da forma verbal “pensamos” (R.49), o autor confere um tom impessoal ao texto. 2 Os adjetivos “pífio” (R.36) e “encharcado” (R.37) e a expressão “exaustão literária” (R. 37 e 38) são empregados, no texto, em sentido conotativo. 3 Sem prejuízo das informações originais do texto e de sua correç | Os comerciantes eram, em grande parte, estrangeiros; o ramo mais saliente do comércio, o ligado ao escravo, sujava as mãos dos que com ele enriqueciam. Um título de comendador ou 7 de barão dourava o busto do empresário, mas não o nobilitava, visto que o nobre pertencia a uma camada diversa, composta, sob o ponto de vista profissional ou econômico, de letrados 10 ou senhores de rendas. O homem que traficava — membro da classe lucrativa ou aquisitiva —, para se qualificar', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q8 Item 1 (TPS 2017): Com referência ao texto IV, julgue (C ou E) os itens que se seguem. | Conforme o texto, tanto o Dr. Félix, personagem de Ressurreição, quanto Rubião, personagem de Quincas Borba, mantinham, em seus negócios e investimentos, condutas que seguiam princípios éticos e morais opostos aos de um homem de comércio como Mauá, que pertencia à ordem dominante.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q8 Item 2 (TPS 2017): Com referência ao texto IV, julgue (C ou E) os itens que se seguem. | Conclui-se do texto que a maioria dos comerciantes, no Império, não era formada por brasileiros, bem como que o comércio mais lucrativo praticado na época estava associado à economia escravocrata.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q8 Item 3 (TPS 2017): Com referência ao texto IV, julgue (C ou E) os itens que se seguem. | Raymundo Faoro argumenta que personagens de romances, tais como Palha e Cotrim, anteciparam, em meados do século XIX, tendências econômicas e políticas que estariam plenamente consolidadas ao final do Império brasileiro.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q8 Item 4 (TPS 2017): Com referência ao texto IV, julgue (C ou E) os itens que se seguem. | Salienta-se, no texto, a importância da renda como atributo de grande reconhecimento social, o que levou Mauá a vivenciar ‘uma luta vivaz’ (R.50), isto é, um dilema, entre a utilização do capital para fins próprios e o investimento na economia nacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q9 Item 1 (TPS 2017): Com referência ao texto IV, julgue (C ou E) os próximos itens. | Tendo o pronome oblíquo sentido possessivo em “sem consultar-lhe as preferências” (R.63), tal trecho poderia ser substituído por sem consultar as suas preferências, mantendo-se, com isso, a correção gramatical e o sentido do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q9 Item 2 (TPS 2017): Com referência ao texto IV, julgue (C ou E) os próximos itens. | A colocação do pronome em “embriagou-se” (R.12), “Elevava-se” (R.14), ‘Já se vê’ (R.47) e “que se identificaria” (R.55) está de acordo com a variedade formal culta da língua portuguesa e deve-se a razões fonético-sintáticas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q9 Item 3 (TPS 2017): Com referência ao texto IV, julgue (C ou E) os próximos itens. | Na linha 23, o emprego da vírgula logo após a expressão “da nova dinâmica” bem como o emprego do artigo definido em “da” indicam que a oração “que agita e move a sociedade” (R.24) não participa da construção da referência dessa expressão.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q9 Item 4 (TPS 2017): Com referência ao texto IV, julgue (C ou E) os próximos itens. | Tanto em “do albardeiro ao círculo dos fidalgos” (R. 20 e 21) quanto em “dos doze aos trinta e dois anos” (R.41), a preposição de foi empregada no sentido de desde.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Portuguesa', NULL, 'Q10 Item 1 (TPS 2017): Julgue (C ou E) os itens subsequentes, acerca das ideias e das estruturas linguísticas do texto IV. | Feitos os devidos ajustes de maiúsculas e minúsculas e de pontuação, o deslocamento dos advérbios “socialmente” e “perdidamente”, ambos na linha12, para o início e para o fim do período em que eles ocorrem, respectivamente, manteria a correção e o sentido original do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Portuguesa', NULL, 'Q10 Item 2 (TPS 2017): Julgue (C ou E) os itens subsequentes, acerca das ideias e das estruturas linguísticas do texto IV. | Os vocábulos “pejada” (R.25) e “aquinhoados” (R.29) podem ser substituídos, respectivamente, por embaraçada e contemplados, sem prejuízo para as informações veiculadas no texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Portuguesa', NULL, 'Q10 Item 3 (TPS 2017): Julgue (C ou E) os itens subsequentes, acerca das ideias e das estruturas linguísticas do texto IV. | Na linha 65, a substituição de “não obstante” por contudo preservaria a correção gramatical e o sentido original do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Portuguesa', NULL, 'Q10 Item 4 (TPS 2017): Julgue (C ou E) os itens subsequentes, acerca das ideias e das estruturas linguísticas do texto IV. | Apesar da cacofonia inicial, a correção gramatical e o sentido original do texto seriam mantidos caso o trecho “Um título de comendador ou de barão dourava o busto do empresário, mas não o nobilitava” (R. 6 e 7) fosse reescrito da seguinte forma: Comenda de comendador ou de barão dourava o busto de comerciantes, embora não lhes tornasse nobre. POLÍTICA INTERNACIONAL', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Política Internacional', NULL, 'Q11 Item 1 (TPS 2017): O processo de saída do Reino Unido da União Europeia — conhecido em inglês como Brexit — coloca desafios tanto para o governo britânico quanto para os demais países europeus. A esse respeito, julgue (C ou E) os itens a seguir. | As negociações para a saída do Reino Unido da União Europeia foram formalmente iniciadas, em março do corrente ano, pela primeira-ministra Theresa May, com o acionamento do artigo 50 do Tratado de Lisboa, após ela ter obtido autorização do parlamento britânico, e devem ser concluídas em dois anos, podendo, porém, ser prorrogadas caso haja consenso entre todos os envolvidos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Política Internacional', NULL, 'Q11 Item 2 (TPS 2017): O processo de saída do Reino Unido da União Europeia — conhecido em inglês como Brexit — coloca desafios tanto para o governo britânico quanto para os demais países europeus. A esse respeito, julgue (C ou E) os itens a seguir. | Embora a opção de saída (leave) tenha sido vitoriosa na contagem total dos votos, os eleitores da Escócia e da Irlanda do Norte votaram majoritariamente contra a saída (remain) do Reino Unido da União Europeia.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Política Internacional', NULL, 'Q11 Item 3 (TPS 2017): O processo de saída do Reino Unido da União Europeia — conhecido em inglês como Brexit — coloca desafios tanto para o governo britânico quanto para os demais países europeus. A esse respeito, julgue (C ou E) os itens a seguir. | Ainda que o Reino Unido deixe o bloco, terá de manter com a União Europeia um regime de livre comércio, já que o Brexit aplica-se exclusivamente às questões de imigração, à participação na elaboração de normas comunitárias e à aplicação das decisões das cortes europeias no território britânico.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Política Internacional', NULL, 'Q11 Item 4 (TPS 2017): O processo de saída do Reino Unido da União Europeia — conhecido em inglês como Brexit — coloca desafios tanto para o governo britânico quanto para os demais países europeus. A esse respeito, julgue (C ou E) os itens a seguir. | A derrota da posição do governo trabalhista de David Cameron, que defendeu a permanência do Reino Unido na União Europeia, levou à formação de um governo pela oposição, liderado pela conservadora Theresa May, uma das principais defensoras do Brexit.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q12 Item 1 (TPS 2017): Com referência à evolução recente do Mercado Comum do Sul (MERCOSUL), que já conta com vinte e cinco anos de existência, julgue (C ou E) os itens que se seguem. | A Venezuela foi suspensa do MERCOSUL em dezembro de 2016 em razão da aplicação da cláusula democrática do Protocolo de Ushuaia.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q12 Item 4 (TPS 2017): Com referência à evolução recente do Mercado Comum do Sul (MERCOSUL), que já conta com vinte e cinco anos de existência, julgue (C ou E) os itens que se seguem. | O MERCOSUL tem buscado ampliar o número de acordos com outros países e blocos, o que pode ser exemplificado pela retomada das negociações para um acordo com a União Europeia e pela busca de maior cooperação com a Aliança do Pacífico. CESPE | CEBRASPE – IRBr – Aplicação: 2017', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q13 Item 1 (TPS 2017): O governo de Juscelino Kubitschek (1956-1960) foi caracterizado pela ênfase nos projetos de desenvolvimento econômico, por meio de ações voltadas para a industrialização e de investimentos em infraestrutura. Essa agenda interna influenciou também a formulação de sua política externa. A respeito da atuação externa do Brasil durante a gestão de Juscelino Kubitschek (JK), julgue (C ou E) os próximos itens. | O debate sobre a Operação Pan-Americana acabou contribuindo para que fosse concretizada uma das aspirações dos países latino-americanos: a criação de uma instituição para financiar projetos de desenvolvimento na região, o Banco Interamericano de Desenvolvimento, cujas operações tiveram início em 1960.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q13 Item 2 (TPS 2017): O governo de Juscelino Kubitschek (1956-1960) foi caracterizado pela ênfase nos projetos de desenvolvimento econômico, por meio de ações voltadas para a industrialização e de investimentos em infraestrutura. Essa agenda interna influenciou também a formulação de sua política externa. A respeito da atuação externa do Brasil durante a gestão de Juscelino Kubitschek (JK), julgue (C ou E) os próximos itens. | O governo de JK buscou ativamente o apoio norte-americano para o desenvolvimento da América Latina, por meio da Operação Pan-Americana. Seus esforços, porém, encontraram resistências nos Estados Unidos da América e nas instituições financeiras internacionais. A dificuldade em obter acesso a financiamentos externos levou, inclusive, ao rompimento do Brasil com o Fundo Monetário Internacional em 1959.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q13 Item 3 (TPS 2017): O governo de Juscelino Kubitschek (1956-1960) foi caracterizado pela ênfase nos projetos de desenvolvimento econômico, por meio de ações voltadas para a industrialização e de investimentos em infraestrutura. Essa agenda interna influenciou também a formulação de sua política externa. A respeito da atuação externa do Brasil durante a gestão de Juscelino Kubitschek (JK), julgue (C ou E) os próximos itens. | No âmbito multilateral, o Brasil alterou sua posição tradicional e passou a criticar, na ONU, a política colonialista de Portugal.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q13 Item 4 (TPS 2017): O governo de Juscelino Kubitschek (1956-1960) foi caracterizado pela ênfase nos projetos de desenvolvimento econômico, por meio de ações voltadas para a industrialização e de investimentos em infraestrutura. Essa agenda interna influenciou também a formulação de sua política externa. A respeito da atuação externa do Brasil durante a gestão de Juscelino Kubitschek (JK), julgue (C ou E) os próximos itens. | O governo de JK reatou relações comerciais com a União das Repúblicas Socialistas Soviéticas, sem, no entanto, restabelecer as relações diplomáticas em sua plenitude.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q14 Item 1 (TPS 2017): Desde 2011, a crise na Síria tem gerado sérias dissensões entre os membros do Conselho de Segurança da ONU, colocando em xeque a capacidade do órgão de oferecer solução para um dos mais graves conflitos do mundo. No que concerne à atuação da ONU e à posição do Brasil a respeito do conflito sírio, julgue (C ou E) os itens subsequentes. | Sob a coordenação de Staffan de Mistura, enviado especial da ONU, têm sido realizadas, em Genebra, negociações para a resolução do conflito sírio, das quais a oposição síria participa, representada pelo chamado Alto Comitê de Negociações (HNC — High Negotiations Committee).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q14 Item 2 (TPS 2017): Desde 2011, a crise na Síria tem gerado sérias dissensões entre os membros do Conselho de Segurança da ONU, colocando em xeque a capacidade do órgão de oferecer solução para um dos mais graves conflitos do mundo. No que concerne à atuação da ONU e à posição do Brasil a respeito do conflito sírio, julgue (C ou E) os itens subsequentes. | Como forma de evitar a deterioração de sua relação com as potências ocidentais — o que poderia colocar em risco o acordo em torno de seu programa nuclear —, o Irã tem buscado não se envolver diretamente no conflito sírio, apesar de já haver manifestado simpatia aos grupos rebeldes de oposição.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q14 Item 3 (TPS 2017): Desde 2011, a crise na Síria tem gerado sérias dissensões entre os membros do Conselho de Segurança da ONU, colocando em xeque a capacidade do órgão de oferecer solução para um dos mais graves conflitos do mundo. No que concerne à atuação da ONU e à posição do Brasil a respeito do conflito sírio, julgue (C ou E) os itens subsequentes. | Ante a incapacidade do Conselho de Segurança em conter o conflito na Síria, o Brasil passou a apoiar firmemente a busca de uma solução em foros alternativos, sem a participação da ONU, tendo chegado a defender, por meio de nota oficial, uma intervenção humanitária com o propósito de se criar uma zona de exclusão aérea e viabilizar a criação de corredores para a assistência a civis.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q14 Item 4 (TPS 2017): Desde 2011, a crise na Síria tem gerado sérias dissensões entre os membros do Conselho de Segurança da ONU, colocando em xeque a capacidade do órgão de oferecer solução para um dos mais graves conflitos do mundo. No que concerne à atuação da ONU e à posição do Brasil a respeito do conflito sírio, julgue (C ou E) os itens subsequentes. | O governo russo alega ter agido a pedido do governo sírio na intervenção militar na Síria iniciada em setembro de 2015, que fortaleceu o regime de Bashar al Assad e ajudou a conter o avanço da oposição armada.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q15 Item 1 (TPS 2017): Em 2011, na esteira da crise na Líbia, o governo brasileiro apresentou na ONU o conceito de responsabilidade ao proteger — responsibility while protecting. Essa foi uma tentativa do Brasil de influenciar os debates sobre o papel da comunidade internacional na resolução de conflitos internos. Julgue (C ou E) os seguintes itens, considerando a posição brasileira sobre o tema. | Apesar da oposição de alguns membros permanentes do Conselho de Segurança, o conceito de responsabilidade ao proteger e os seus consequentes mecanismos de monitoramento e avaliação do uso da força foram incorporados ao acervo normativo da ONU, estando vigentes, embora ainda não tenham sido aplicados a um caso concreto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q15 Item 2 (TPS 2017): Em 2011, na esteira da crise na Líbia, o governo brasileiro apresentou na ONU o conceito de responsabilidade ao proteger — responsibility while protecting. Essa foi uma tentativa do Brasil de influenciar os debates sobre o papel da comunidade internacional na resolução de conflitos internos. Julgue (C ou E) os seguintes itens, considerando a posição brasileira sobre o tema. | Com a proposição do conceito de responsabilidade ao proteger, buscava-se complementar o conceito de responsabilidade de proteger, defendendo-se que o uso da força seja, sempre, o último recurso e esteja amparado em meios adequados (proporcionais e limitados aos objetivos do mandato), de modo a não engendrar um agravamento do quadro de violência.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q15 Item 3 (TPS 2017): Em 2011, na esteira da crise na Líbia, o governo brasileiro apresentou na ONU o conceito de responsabilidade ao proteger — responsibility while protecting. Essa foi uma tentativa do Brasil de influenciar os debates sobre o papel da comunidade internacional na resolução de conflitos internos. Julgue (C ou E) os seguintes itens, considerando a posição brasileira sobre o tema. | Um dos aspectos inovadores do conceito de responsabilidade ao proteger foi a ênfase na necessidade de que se estabelecessem, no âmbito do Conselho de Segurança da ONU, mecanismos de monitoramento e avaliação, de modo a aferir a responsabilidade daqueles que recebessem autorização para o uso da força.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q15 Item 4 (TPS 2017): Em 2011, na esteira da crise na Líbia, o governo brasileiro apresentou na ONU o conceito de responsabilidade ao proteger — responsibility while protecting. Essa foi uma tentativa do Brasil de influenciar os debates sobre o papel da comunidade internacional na resolução de conflitos internos. Julgue (C ou E) os seguintes itens, considerando a posição brasileira sobre o tema. | Para o Brasil, a intervenção militar na Líbia, embora autorizada pelo Conselho de Segurança da ONU, constituiria um exemplo do uso indevido do conceito de responsabilidade de proteger, ao servir de instrumento para a promoção da mudança de regime político, o que extrapolaria o mandato concedido pelo Conselho de Segurança.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q16 Item 1 (TPS 2017): Tendo em vista que o Acordo das Nações Unidas sobre Mudança do Clima (Acordo de Paris), assinado em 2015, constituiu um marco nos esforços da comunidade internacional para reduzir a emissão de gases de efeito estufa, julgue (C ou E) os itens subsecutivos, relativos a esse acordo. | Uma das principais inovações do acordo é o fato de ele não estabelecer metas uniformes para todos os signatários, tendo cada país indicado metas voluntárias que pretende cumprir, as chamadas Pretendidas Contribuições Nacionalmente Determinadas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q16 Item 2 (TPS 2017): Tendo em vista que o Acordo das Nações Unidas sobre Mudança do Clima (Acordo de Paris), assinado em 2015, constituiu um marco nos esforços da comunidade internacional para reduzir a emissão de gases de efeito estufa, julgue (C ou E) os itens subsecutivos, relativos a esse acordo. | A contribuição brasileira às metas do acordo contempla o aumento da participação de energias renováveis em sua matriz energética, mas não inclui compromissos no âmbito florestal, seja de redução do desmatamento, seja de reflorestamento.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q16 Item 4 (TPS 2017): Tendo em vista que o Acordo das Nações Unidas sobre Mudança do Clima (Acordo de Paris), assinado em 2015, constituiu um marco nos esforços da comunidade internacional para reduzir a emissão de gases de efeito estufa, julgue (C ou E) os itens subsecutivos, relativos a esse acordo. | Embora tenha sido assinado por quase duas centenas de países, o acordo ainda não entrou em vigor, já que muitos desses países ainda não o ratificaram. CESPE | CEBRASPE – IRBr – Aplicação: 2017', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q17 Item 1 (TPS 2017): O tema da segurança, nacional e coletiva, faz parte da história da política exterior do Brasil. A respeito desse tema, julgue (C ou E) os itens seguintes. | A reunião ministerial do Cone Sul sobre a Segurança nas Fronteiras, realizada em Brasília em novembro de 2016, ciente de que o tráfico ilícito de armas de fogo, munições e explosivos e de drogas alimenta a violência nos países da região, decidiu promover cooperação judicial, policial e de suas agências de inteligência, para combater a criminalidade organizada transnacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q17 Item 2 (TPS 2017): O tema da segurança, nacional e coletiva, faz parte da história da política exterior do Brasil. A respeito desse tema, julgue (C ou E) os itens seguintes. | Criada por resolução da Assembleia Geral da ONU em 1986, a Zona de Paz e Cooperação do Atlântico Sul é integrada por países banhados por esse oceano, inclusive o Brasil, e realizou várias reuniões ministeriais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q17 Item 3 (TPS 2017): O tema da segurança, nacional e coletiva, faz parte da história da política exterior do Brasil. A respeito desse tema, julgue (C ou E) os itens seguintes. | Na reunião de cúpula da União de Nações Sul-Americanas, em 2008, foi aprovada a proposta brasileira de criação do Conselho de Defesa Sul-Americano, com caráter de aliança militar, no âmbito da qual se pretendem constituir, até 2025, unidades militares integradas por forças dos diferentes países-membros para serem empregadas com finalidade defensiva.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q17 Item 4 (TPS 2017): O tema da segurança, nacional e coletiva, faz parte da história da política exterior do Brasil. A respeito desse tema, julgue (C ou E) os itens seguintes. | O Brasil contribui com as forças de paz da ONU desde a década de 50 do século XX, quando soldados brasileiros participaram da Força de Emergência das Nações Unidas, criada para evitar conflitos entre egípcios e israelenses e pôr fim à Crise de Suez; cabe ao Brasil, atualmente, o comando da missão de paz da Força-Tarefa Marítima da Força Interina das Nações Unidas no Líbano.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q18 Item 1 (TPS 2017): O Brasil, no contexto das chamadas “nações periféricas”, foi um dos países que mais participou do sistema internacional no último século e meio de surgimento, consolidação e expansão dos organismos econômicos multilaterais. Paulo Roberto Almeida. Relações internacionais e política externa do Brasil. Rio de Janeiro: LTC, 2012, p. 213. Tendo o fragmento de texto anterior como referência inicial, julgue (C ou E) os próximos itens, a respeito da atuação do Brasil no âmbito do multilateralismo econôm | O Brasil fez parte do grupo de países que defendeu a criação da Organização para a Proibição de Armas Químicas, agência especializada da ONU diretamente subordinada ao secretário-geral desse organismo internacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q18 Item 2 (TPS 2017): O Brasil, no contexto das chamadas “nações periféricas”, foi um dos países que mais participou do sistema internacional no último século e meio de surgimento, consolidação e expansão dos organismos econômicos multilaterais. Paulo Roberto Almeida. Relações internacionais e política externa do Brasil. Rio de Janeiro: LTC, 2012, p. 213. Tendo o fragmento de texto anterior como referência inicial, julgue (C ou E) os próximos itens, a respeito da atuação do Brasil no âmbito do multilateralismo econôm | No contexto das estreitas relações entre o governo de Castelo Branco e os Estados Unidos da América, o Brasil enviou tropa para participar da Força Interamericana de Paz, criada em 1965 pela Organização dos Estados Americanos para contribuir na pacificação da República Dominicana, então abalada por uma guerra civil.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q18 Item 3 (TPS 2017): O Brasil, no contexto das chamadas “nações periféricas”, foi um dos países que mais participou do sistema internacional no último século e meio de surgimento, consolidação e expansão dos organismos econômicos multilaterais. Paulo Roberto Almeida. Relações internacionais e política externa do Brasil. Rio de Janeiro: LTC, 2012, p. 213. Tendo o fragmento de texto anterior como referência inicial, julgue (C ou E) os próximos itens, a respeito da atuação do Brasil no âmbito do multilateralismo econôm | Instituição subordinada ao Fundo Monetário Internacional, o Clube de Paris atua na coordenação de renegociação de dívidas contraídas entre Estados e dele o Brasil desfiliou-se tão logo saldou a totalidade de sua dívida pública externa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q18 Item 4 (TPS 2017): O Brasil, no contexto das chamadas “nações periféricas”, foi um dos países que mais participou do sistema internacional no último século e meio de surgimento, consolidação e expansão dos organismos econômicos multilaterais. Paulo Roberto Almeida. Relações internacionais e política externa do Brasil. Rio de Janeiro: LTC, 2012, p. 213. Tendo o fragmento de texto anterior como referência inicial, julgue (C ou E) os próximos itens, a respeito da atuação do Brasil no âmbito do multilateralismo econôm | Tanto as sessões constitutivas do Acordo Geral sobre Tarifas Aduaneiras e Comércio (1947) quanto a Conferência de Comércio e Emprego das Nações Unidas (1947-1948) contaram com a participação de representantes do Brasil.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q19 Item 1 (TPS 2017): A Argentina é, historicamente, uma prioridade para a política externa brasileira. Em seu estágio atual, as relações entre os dois países caracterizam-se pela busca da integração econômica e da cooperação política. A respeito da política externa Argentina, julgue (C ou E) os itens que se seguem. | Durante o período de Carlos Menem na presidência argentina (1989-1999), sua política externa alinhou-se com as posições dos Estados Unidos da América no contexto internacional, enquanto surgiram críticas, de fontes oficiais e privadas, sobre uma “Brasil dependência” por parte da Argentina.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q19 Item 2 (TPS 2017): A Argentina é, historicamente, uma prioridade para a política externa brasileira. Em seu estágio atual, as relações entre os dois países caracterizam-se pela busca da integração econômica e da cooperação política. A respeito da política externa Argentina, julgue (C ou E) os itens que se seguem. | Durante o primeiro período de Juan Domingo Perón na presidência argentina (1946-1955), a diplomacia do país resolveu o problema da demarcação dos limites fronteiriços nos Andes Patagônicos, aceitou a reivindicação uruguaia relativa ao limite fronteiriço no estuário do rio da Prata e propôs uma coordenação política entre Argentina, Brasil e Chile para tratar dos assuntos internacionais mais importantes.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q19 Item 3 (TPS 2017): A Argentina é, historicamente, uma prioridade para a política externa brasileira. Em seu estágio atual, as relações entre os dois países caracterizam-se pela busca da integração econômica e da cooperação política. A respeito da política externa Argentina, julgue (C ou E) os itens que se seguem. | As relações entre Brasil e Argentina, entre 1955 e 1964, caracterizaram-se pela crescente cordialidade, como o demonstram o apoio do presidente Arturo Frondizi à Operação Pan-Americana, proposta pelo presidente Juscelino Kubitschek, e o acordo de cooperação militar assinado entre os presidentes Frondizi e Jânio Quadros, no encontro de Uruguaiana, em 1961.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q19 Item 4 (TPS 2017): A Argentina é, historicamente, uma prioridade para a política externa brasileira. Em seu estágio atual, as relações entre os dois países caracterizam-se pela busca da integração econômica e da cooperação política. A respeito da política externa Argentina, julgue (C ou E) os itens que se seguem. | Em 1990, os governos brasileiro e argentino criaram o grupo de trabalho binacional denominado Grupo Mercado Comum, para elaborar e propor medidas que propiciassem a criação do mercado comum Brasil-Argentina até o ano de 1994.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q20 Item 1 (TPS 2017): Acerca dos direitos humanos e de questões de gênero na política internacional, julgue (C ou E) os itens a seguir. | Direitos sociais relacionados à proteção do trabalho foram incluídos na Declaração Universal dos Direitos Humanos das Nações Unidas em consequência da iniciativa do representante brasileiro no comitê de redação.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q20 Item 2 (TPS 2017): Acerca dos direitos humanos e de questões de gênero na política internacional, julgue (C ou E) os itens a seguir. | A promoção dos direitos das mulheres constituiu um aspecto importante da política externa norte-americana no período em que Hilary Clinton ocupou o posto de secretária de Estado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q20 Item 3 (TPS 2017): Acerca dos direitos humanos e de questões de gênero na política internacional, julgue (C ou E) os itens a seguir. | Em 2015, o Reino Unido pôs em prática uma política externa feminista centrada na tríade: representação, direitos e recursos, o que gerou tensões com países árabes como a Arábia Saudita e o Egito.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Língua Inglesa', NULL, 'Q20 Item 4 (TPS 2017): Acerca dos direitos humanos e de questões de gênero na política internacional, julgue (C ou E) os itens a seguir. | Apesar dos esforços da delegada brasileira Bertha Lutz nas reuniões preparatórias, o texto final da Carta das Nações Unidas, assinado em 1945, não menciona a igualdade entre os sexos. CESPE | CEBRASPE – IRBr – Aplicação: 2017', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Política Internacional', NULL, 'Q21 Item 1 (TPS 2017): Considerando o cenário das relações internacionais nos países do Oriente Médio contemporâneo, julgue (C ou E) os próximos itens. | Segundo o teórico realista das relações internacionais Kenneth Waltz, a posse de uma bomba nuclear pelo Irã geraria estabilidade no Oriente Médio.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Política Internacional', NULL, 'Q21 Item 2 (TPS 2017): Considerando o cenário das relações internacionais nos países do Oriente Médio contemporâneo, julgue (C ou E) os próximos itens. | A questão palestina e a relação de forças entre os atores em conflito nessa região não foram significativamente afetadas pelas transformações decorrentes da Primavera Árabe.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Política Internacional', NULL, 'Q21 Item 3 (TPS 2017): Considerando o cenário das relações internacionais nos países do Oriente Médio contemporâneo, julgue (C ou E) os próximos itens. | O bloqueio imposto ao Catar por um conjunto de países árabes em junho de 2017 deveu-se à convicção de que o governo catarense não vinha empreendendo esforços suficientes para combater o terrorismo, além de manter relações de cooperação com o Irã.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Política Internacional', NULL, 'Q21 Item 4 (TPS 2017): Considerando o cenário das relações internacionais nos países do Oriente Médio contemporâneo, julgue (C ou E) os próximos itens. | Os conflitos no Barein, na Síria e no Iêmen estão estreitamente relacionados à luta pela hegemonia regional travada entre o Irã e a Arábia Saudita.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Política Internacional', NULL, 'Q22 Item 1 (TPS 2017): A respeito de alguns dos principais paradigmas teóricos referentes ao estudo das relações internacionais, julgue (C ou E) os itens que se seguem. | Nas teorias feministas das relações internacionais é comum o argumento de que questões relativas à reflexividade e à subjetividade devem ser excluídas das pesquisas, de modo a evitar prejuízos ao ideal da objetividade do conhecimento.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Política Internacional', NULL, 'Q22 Item 2 (TPS 2017): A respeito de alguns dos principais paradigmas teóricos referentes ao estudo das relações internacionais, julgue (C ou E) os itens que se seguem. | Um argumento importante desenvolvido pelo teórico idealista Norman Angell é o de que a guerra não é economicamente proveitosa para os países agressores.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Política Internacional', NULL, 'Q22 Item 3 (TPS 2017): A respeito de alguns dos principais paradigmas teóricos referentes ao estudo das relações internacionais, julgue (C ou E) os itens que se seguem. | A metodologia eclética e pluralista típica da escola inglesa decorre das especificidades das seguintes categorias analíticas: sistema internacional, sociedade internacional e sociedade mundial.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Política Internacional', NULL, 'Q22 Item 4 (TPS 2017): A respeito de alguns dos principais paradigmas teóricos referentes ao estudo das relações internacionais, julgue (C ou E) os itens que se seguem. | Um dos princípios do realismo político de Hans Morgenthau é o de que o interesse dos Estados nunca pode ser definido exclusivamente em termos de poder. GEOGRAFIA', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Geografia', NULL, 'Q23 Item 1 (TPS 2017): Com relação aos fundamentos e ao desenvolvimento da geografia científica, julgue (C ou E) os itens a seguir. | Desde a geografia clássica até o presente, pensamento e prática geográfica conformam métodos e metodologias bem definidos, não havendo antagonismos dos tipos forma/conteúdo, objetividade/subjetividade, explicativa/compreensiva, matemática/descritiva.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Geografia', NULL, 'Q23 Item 2 (TPS 2017): Com relação aos fundamentos e ao desenvolvimento da geografia científica, julgue (C ou E) os itens a seguir. | A adoção da teoria geral dos sistemas pela geografia do século XX levou à crença de que fenômenos, como, por exemplo, dos movimentos migratórios à dinâmica da natureza, podem ser entendidos utilizando-se o cálculo de probabilidades, que permite prever ou antecipar fatos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Geografia', NULL, 'Q23 Item 3 (TPS 2017): Com relação aos fundamentos e ao desenvolvimento da geografia científica, julgue (C ou E) os itens a seguir. | Atribuir o surgimento da geografia científica — moderna — a Carl Ritter e a Alexander Humboldt é fundamental, mas sem renegar o conhecimento geográfico produzido antes desses autores.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Geografia', NULL, 'Q23 Item 4 (TPS 2017): Com relação aos fundamentos e ao desenvolvimento da geografia científica, julgue (C ou E) os itens a seguir. | Carl Ritter e Alexander Humboldt ofereceram, em suas obras, um discurso que criou a nova ciência geográfica, simultaneamente cosmológica e regional, o que fez do geógrafo um observador da natureza capaz de somar prazer estético e prazer intelectual para compreender as leis naturais; tais princípios estavam presentes no pensamento e na prática nacionalista europeia do final do século XIX, dependentes de análises sistemáticas e particulares sobre o território.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Geografia', NULL, 'Q24 Item 1 (TPS 2017): Julgue (C ou E) os itens subsequentes, a respeito da economia espacial brasileira ao longo dos séculos XX e XXI. | As resultantes históricas da economia espacial brasileira demonstram que as desigualdades territoriais e regionais têm por base menos o estoque de capital e mais as aptidões produtivas da força de trabalho e a aptidão em elaborar bens novos e processos técnicos avançados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Geografia', NULL, 'Q24 Item 2 (TPS 2017): Julgue (C ou E) os itens subsequentes, a respeito da economia espacial brasileira ao longo dos séculos XX e XXI. | A história do desenvolvimento da produção de energia e da logística no país, atrelada à história da formação territorial nacional, resulta na produção de espacialidades técnicas, notoriamente, na denominada Região Concentrada brasileira.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Geografia', NULL, 'Q24 Item 3 (TPS 2017): Julgue (C ou E) os itens subsequentes, a respeito da economia espacial brasileira ao longo dos séculos XX e XXI. | A construção de Brasília como nova capital brasileira, a partir de 1956, foi motivada, entre outros aspectos, pelo crescimento da indústria automobilística, pelo protagonismo do capital financeiro na economia e pela emergência das cidades do campo na região Centro-Oeste.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Geografia', NULL, 'Q24 Item 4 (TPS 2017): Julgue (C ou E) os itens subsequentes, a respeito da economia espacial brasileira ao longo dos séculos XX e XXI. | As cidades médias têm apresentado, na atualidade, retração dos índices econômico e tecnológico em decorrência do poder de atração e concentração exercido pelas metrópoles nacionais e regionais. CESPE | CEBRASPE – IRBr – Aplicação: 2017', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q25 Item 1 (TPS 2017): Considerando a tríade cidade, ambiente e cultura, julgue (C ou E) os seguintes itens. | No Brasil, as periferias metropolitanas podem ser caracterizadas por trazerem elementos de reprodução da vida rural pregressa do país, como são, por exemplo, os casos de Goiânia, São Paulo e Belo Horizonte.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q25 Item 2 (TPS 2017): Considerando a tríade cidade, ambiente e cultura, julgue (C ou E) os seguintes itens. | As periferias enquanto espaço social são lugares de construção cultural cotidiana influenciadas pela cultura de massas, que é parte da indústria cultural, e retroalimentam esse setor da economia quando suas manifestações culturais são apropriadas e transformadas em produtos consumidos em escala local, regional e global.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q25 Item 3 (TPS 2017): Considerando a tríade cidade, ambiente e cultura, julgue (C ou E) os seguintes itens. | No cerne de uma nova regionalização brasileira, catalisada pelo poder estratégico-econômico do Sudeste e do Sul, populações indígenas e quilombolas do Centro-Oeste e do Norte têm migrado para cidades do campo daquelas regiões, tornando-se a mão de obra qualificada nesses novos centros.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q25 Item 4 (TPS 2017): Considerando a tríade cidade, ambiente e cultura, julgue (C ou E) os seguintes itens. | Nas cidades, as denominadas áreas de risco constituem-se à revelia das políticas espaciais adotadas tanto pelos municípios quanto pelos empreendedores imobiliários, em um processo no qual a população ocupante torna-se a responsável pela constituição do risco e da vulnerabilidade. Espaço livre', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q26 Item 1 (TPS 2017): Atualmente, dos dez países mais populosos do mundo, um está na África (Nigéria), cinco na Ásia (Bangladesh, China, Índia, Indonésia e Paquistão), dois na América Latina (Brasil e México), um na América Anglo-saxônica (EUA) e um na Europa (Rússia). Sétima maior população do mundo, a Nigéria é o país que apresenta maior ritmo de crescimento, e deve ultrapassar os EUA até 2050, passando a ocupar a terceira posição entre os mais populosos. A atual população mundial de 7,3 bilhões de pessoas vai alca | No contexto de integração econômica regional, a permeabilidade das fronteiras dos países da América Latina vem contribuindo para a intensificação dos deslocamentos de população entre países, com um conjunto significativo de migrantes deslocando-se de forma clandestina ou ilegal, o que dificulta a mensuração dos fluxos migratórios entre países.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q26 Item 2 (TPS 2017): Atualmente, dos dez países mais populosos do mundo, um está na África (Nigéria), cinco na Ásia (Bangladesh, China, Índia, Indonésia e Paquistão), dois na América Latina (Brasil e México), um na América Anglo-saxônica (EUA) e um na Europa (Rússia). Sétima maior população do mundo, a Nigéria é o país que apresenta maior ritmo de crescimento, e deve ultrapassar os EUA até 2050, passando a ocupar a terceira posição entre os mais populosos. A atual população mundial de 7,3 bilhões de pessoas vai alca | Devido ao envelhecimento da população, à diminuição drástica das taxas de natalidade e à necessidade de mão de obra jovem para manter sua economia, diversos países da União Europeia têm adotado políticas de legitimação de migrações ilegais e de concessão de asilo político.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q26 Item 3 (TPS 2017): Atualmente, dos dez países mais populosos do mundo, um está na África (Nigéria), cinco na Ásia (Bangladesh, China, Índia, Indonésia e Paquistão), dois na América Latina (Brasil e México), um na América Anglo-saxônica (EUA) e um na Europa (Rússia). Sétima maior população do mundo, a Nigéria é o país que apresenta maior ritmo de crescimento, e deve ultrapassar os EUA até 2050, passando a ocupar a terceira posição entre os mais populosos. A atual população mundial de 7,3 bilhões de pessoas vai alca | O crescimento demográfico mundial apresenta uma face perversa: se, por um lado, há crescimento vegetativo motivado pelas melhores condições de vida em países pobres, por outro, a expectativa de vida ainda continua relativamente baixa em países como o Brasil, a China e a Índia, descompasso justificado por aspectos como a violência e as doenças crônicas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q26 Item 4 (TPS 2017): Atualmente, dos dez países mais populosos do mundo, um está na África (Nigéria), cinco na Ásia (Bangladesh, China, Índia, Indonésia e Paquistão), dois na América Latina (Brasil e México), um na América Anglo-saxônica (EUA) e um na Europa (Rússia). Sétima maior população do mundo, a Nigéria é o país que apresenta maior ritmo de crescimento, e deve ultrapassar os EUA até 2050, passando a ocupar a terceira posição entre os mais populosos. A atual população mundial de 7,3 bilhões de pessoas vai alca | O início do século XXI tem sido marcado pela intensificação da crise migratória global, pela entrada em massa de refugiados e ilegais no continente europeu, e pela pauta, na agenda política de diversos países, do tema da migração internacional, sendo o Brasil, nesse cenário, um dos integrantes das rotas de migrações internacionais. CESPE | CEBRASPE – IRBr – Aplicação: 2017', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q27 Item 2 (TPS 2017): Foi a partir da realização da Conferência Eco 92, da qual resultou o Tratado de Quioto (em 1997), que a busca por energia menos poluente e renovável tornou-se uma prioridade em alguns países, como a China e o Japão, que passaram a adicionar álcool (etanol anidro) à gasolina, na busca de diminuir o uso do petróleo e a emissão de monóxido de carbono, um dos gases responsáveis pelo efeito estufa. A partir daí, iniciou-se uma fase de preocupação mundial pela proteção ambiental, por meio da criação d | A China e a União Europeia adotaram políticas de geração de energia e de desenvolvimento de tecnologias limpas como estratégias para o cumprimento do acordo de Paris (2015), e a competição entre países na geração de energia limpa poderá ser um dos elementos de reordenamento do território, da produção e da competitividade entre países no mundo globalizado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q27 Item 3 (TPS 2017): Foi a partir da realização da Conferência Eco 92, da qual resultou o Tratado de Quioto (em 1997), que a busca por energia menos poluente e renovável tornou-se uma prioridade em alguns países, como a China e o Japão, que passaram a adicionar álcool (etanol anidro) à gasolina, na busca de diminuir o uso do petróleo e a emissão de monóxido de carbono, um dos gases responsáveis pelo efeito estufa. A partir daí, iniciou-se uma fase de preocupação mundial pela proteção ambiental, por meio da criação d | No Brasil, o setor sucroalcooleiro, além da produção de açúcar e álcool, tem intensificado a geração de energia a partir da queima da biomassa da cana, o que representa uma alternativa ao tradicional modelo de energia hidrelétrica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q27 Item 4 (TPS 2017): Foi a partir da realização da Conferência Eco 92, da qual resultou o Tratado de Quioto (em 1997), que a busca por energia menos poluente e renovável tornou-se uma prioridade em alguns países, como a China e o Japão, que passaram a adicionar álcool (etanol anidro) à gasolina, na busca de diminuir o uso do petróleo e a emissão de monóxido de carbono, um dos gases responsáveis pelo efeito estufa. A partir daí, iniciou-se uma fase de preocupação mundial pela proteção ambiental, por meio da criação d | Um dos pontos de discordância que justifica a saída do Reino Unido do bloco europeu é a visão dicotômica no que se refere às políticas de geração de energia e uso de fontes alternativas na matriz energética dos países do bloco: o Reino Unido defende o uso intensivo do carvão mineral, considerado altamente poluente, porém abundante no arquipélago britânico e de baixo custo de geração de energia, enquanto a União Europeia defende fontes alternativas como as energias solar', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q28 Item 1 (TPS 2017): O Brasil é, na América Latina, um dos países que mais reorganizou sua atividade agropecuária desde meados do século XX. Desde então, a reestruturação produtiva da agricultura brasileira tem-se norteado pela racionalidade com funcionamento regulado pelas relações de produção e distribuição globalizadas, direcionando-se, cada vez mais, ao atendimento da crescente demanda do mercado urbano interno e à produção de commodities para a exportação, in natura ou após passarem por algum tipo de transforma | A expansão da moderna agricultura nos biomas Cerrado e Amazônia tem-se constituído a partir de reduzidos fluxos migratórios em direção às pequenas e médias cidades dessas regiões e de poucos conflitos no campo, uma vez que a mecanização excessiva das atividades agrárias gera poucos empregos tanto no campo quanto na cidade.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q28 Item 2 (TPS 2017): O Brasil é, na América Latina, um dos países que mais reorganizou sua atividade agropecuária desde meados do século XX. Desde então, a reestruturação produtiva da agricultura brasileira tem-se norteado pela racionalidade com funcionamento regulado pelas relações de produção e distribuição globalizadas, direcionando-se, cada vez mais, ao atendimento da crescente demanda do mercado urbano interno e à produção de commodities para a exportação, in natura ou após passarem por algum tipo de transforma | As regiões produtivas do agronegócio brasileiro são competitivas no mercado global de commodities e caracterizadas pela especialização produtiva que atende a parâmetros internacionais de qualidade e de custos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q28 Item 3 (TPS 2017): O Brasil é, na América Latina, um dos países que mais reorganizou sua atividade agropecuária desde meados do século XX. Desde então, a reestruturação produtiva da agricultura brasileira tem-se norteado pela racionalidade com funcionamento regulado pelas relações de produção e distribuição globalizadas, direcionando-se, cada vez mais, ao atendimento da crescente demanda do mercado urbano interno e à produção de commodities para a exportação, in natura ou após passarem por algum tipo de transforma | Para atender, principalmente, ao mercado internacional, adotam-se, nas áreas do bioma Cerrado, os modelos de ocupação do território e de produção desenvolvidos pelo agribusiness nos países centrais do capitalismo global, que favorecem a produção em larga escala, intensiva em tecnologia, a partir dos latossolos de média e alta fertilidade.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Economia', NULL, 'Q28 Item 4 (TPS 2017): O Brasil é, na América Latina, um dos países que mais reorganizou sua atividade agropecuária desde meados do século XX. Desde então, a reestruturação produtiva da agricultura brasileira tem-se norteado pela racionalidade com funcionamento regulado pelas relações de produção e distribuição globalizadas, direcionando-se, cada vez mais, ao atendimento da crescente demanda do mercado urbano interno e à produção de commodities para a exportação, in natura ou após passarem por algum tipo de transforma | Característica marcante do atual período da agricultura brasileira é a ocupação de milhões de hectares de cerrado pela agricultura moderna globalizada, ao mesmo tempo em que se aprofundam a divisão territorial do trabalho, os conflitos envolvendo povos e comunidades tradicionais, o uso intensivo dos recursos naturais e a perda de biodiversidade. NOÇÕES DE DIREITO E DIREITO INTERNACIONAL PÚBLICO', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Direito Internacional Público', NULL, 'Q29 Item 1 (TPS 2017): Considerando as disposições constitucionais sobre o processo legislativo brasileiro e as competências da União e dos estados, julgue (C ou E) os itens a seguir. | Como a Constituição não faz referência à iniciativa popular de lei ao dispor sobre o processo legislativo no âmbito estadual, o Supremo Tribunal Federal não reconhece esse instrumento como modalidade explícita de democracia direta.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
